#!/usr/bin/env bun
/**
 * Generate the application this orchestrator runs on /app, from a model.
 *
 *   bun build/generate-app.ts -i <model.eml.yaml | model.cedm.yaml> -o <dir> -n <name> [--force]
 *
 * A thin CLI over the generator in `app-with-ai-rust`, checked out beside this
 * repository: the model is read, validated and compiled by that generator's own
 * loader (`loadModelFile`, the one its `appwithai` CLI uses) and generated by
 * its one pipeline (`generateApplication`). Nothing here decides what a model
 * means. The stack is always `tanstack-astryx-loco`, and `loco new` is skipped:
 * the scaffold only contributes the framework's own CI workflow, rustfmt config
 * and AGENTS.md, and the crate is compiled inside its image, so this machine
 * needs no Rust toolchain.
 */
import { existsSync, rmSync } from "node:fs";
import path from "node:path";
import { parseArgs } from "node:util";
import { loadModelFile } from "../../../app-with-ai-rust/packages/generator/src/cli/model-input.ts";
import { generateApplication } from "../../../app-with-ai-rust/packages/generator/src/pipeline/generate-application.ts";

const { values } = parseArgs({
  options: {
    input: { type: "string", short: "i" },
    output: { type: "string", short: "o" },
    name: { type: "string", short: "n" },
    force: { type: "boolean", default: false },
    help: { type: "boolean", short: "h", default: false },
  },
});

if (values.help || !values.input || !values.output || !values.name) {
  console.log(
    "Usage: bun build/generate-app.ts -i <model.eml.yaml|model.cedm.yaml> -o <dir> -n <name> [--force]"
  );
  process.exit(values.help ? 0 : 2);
}

const input = path.resolve(values.input);
const output = path.resolve(values.output);
if (existsSync(output)) {
  if (!values.force) {
    console.error(`${output} exists. Pass --force to replace it.`);
    process.exit(1);
  }
  rmSync(output, { recursive: true, force: true });
}

let loaded: Awaited<ReturnType<typeof loadModelFile>>;
try {
  loaded = await loadModelFile(input);
} catch (error) {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
}

await generateApplication({
  document: loaded.document,
  modelText: loaded.text,
  ...(loaded.cedm ? { cedm: loaded.cedm } : {}),
  model: loaded.model,
  stackOption: "tanstack-astryx-loco",
  projectName: values.name,
  outputDir: output,
  skipCliScaffold: true,
  manifest: { input: [path.basename(input)] },
});
console.log(`Generated ${values.name} into ${output}`);
